<?php if($type==='account'):?><h3>Información conservada de la solicitud</h3><?php require __DIR__.'/request-snapshot.php'; ?><?php foreach($photos as $photo):?><p><a href="business-reference-image.php?source=application&amp;id=<?=esc($photo['id'])?>" target="_blank" rel="noopener">Ver imagen enviada: <?=esc($photo['original_name'])?> ↗</a></p><?php endforeach ?><?php foreach($evidence as $document):?><p><a href="representation-evidence.php?id=<?=esc($document['id'])?>" target="_blank" rel="noopener"><?=esc($document['original_name'])?> ↗</a> · <?=empty($document['verified_at'])?'Sin revisión documental registrada':'Revisión registrada'?></p><?php endforeach ?><?php endif ?></section>
<section class="card"><h2>Ficha actual</h2><?php if(!$links):?><p>No hay una ficha vinculada a esta solicitud.</p><?php endif ?><?php foreach($links as $link):$business=$linkedBusinesses[(int)$link['business_id']]??false;if(!$business)continue;?><p><strong><?=esc($business['display_name'])?></strong> · #<?=esc($business['id'])?> · <?=esc($business['publication_status'])?> · <?=esc($business['information_status'])?> <a href="businesses.php?id=<?=esc($business['id'])?>" target="_blank" rel="noopener">Abrir negocio ↗</a><?php if(isset($link['created_at'])):?><br><small>Relación informativa registrada: <?=esc($link['created_at'])?> por <?=esc($link['linked_by'])?></small><?php endif ?></p><?php endforeach ?></section>
<section class="card"><h2>Validaciones</h2><p>Una relación informativa o una cuenta asociada no certifica titularidad. Revisar esta página no publica ni envía mensajes.</p><?php if($account):?><p>Cuenta #<?=esc($account['id'])?>: <?=esc($account['name'])?> · <?=esc($account['email'])?> · <?=esc($account['status'])?></p><?php endif ?><?php if($type==='account'):?><?php if($request['status']==='approved'&&!$memberships):?><p class="notice" role="alert">La solicitud figura aprobada, pero no hay una asociación de esta cuenta con la ficha. Revisar la inconsistencia; no se ha reparado automáticamente.</p><?php endif ?><?php foreach($memberships as $membership):?><p>Asociación: <?=esc($membership['status'])?> · <?=esc($membership['role'])?> · <?=esc($membership['created_at'])?></p><?php endforeach ?><p><a href="account-applications.php">Consultar y gestionar la asociación en Solicitudes de cuenta</a></p><?php endif ?></section>
<?php if($type==='lead'):?><section class="card"><h2>Responder a esta solicitud</h2><p><a href="request-response.php?lead=<?=esc($id)?>" target="_blank" rel="noopener">Preparar respuesta y ver historial ↗</a></p><h2>Relacionar con una ficha existente</h2><p>Busca el negocio, comprueba el lugar y confirma su ID. Esta acción conserva los vínculos anteriores y no asigna una cuenta.</p><form method="get" class="registration-form"><input type="hidden" name="type" value="lead"><input type="hidden" name="id" value="<?=esc($id)?>"><?php foreach($returnFields as $key=>$value):?><input type="hidden" name="<?=esc($key)?>" value="<?=esc($value)?>"><?php endforeach ?><label>Nombre del negocio<input name="search" value="<?=esc($search)?>" required maxlength="190"></label><button class="pill">Buscar fichas</button></form><?php if($search!==''&&!$matches):?><p>No hay coincidencias.</p><?php endif ?><?php foreach($matches as $match):?><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($csrfToken)?>"><input type="hidden" name="action" value="link"><input type="hidden" name="business_id" value="<?=esc($match['id'])?>"><p><?=esc($match['display_name'])?> · <?=esc($match['place'])?> · #<?=esc($match['id'])?></p><label><input type="checkbox" name="confirm" value="1" required> Confirmo que esta es la ficha relacionada con la consulta</label><button class="pill">Guardar relación con #<?=esc($match['id'])?></button></form><?php endforeach ?></section><?php endif ?></main></body></html>
